#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
经验提炼脚本
从多个工作流报告中提炼经验、模式和最佳实践
"""

import os
import json
from collections import Counter, defaultdict
from typing import Dict, List, Any
from pathlib import Path
from parse_workflow_report import parse_multiple_reports


def distill_experience(reports_dir: str) -> Dict[str, Any]:
    """
    从多个报告中提炼经验

    Args:
        reports_dir: 报告目录路径

    Returns:
        提炼的经验总结
    """
    # 解析所有报告
    reports = parse_multiple_reports(reports_dir)

    if not reports:
        return {"error": "No reports found"}

    # 提取各类信息
    prompts = extract_all_prompts(reports)
    patterns = identify_patterns(reports)
    error_stats = analyze_errors(reports)
    best_practices = extract_best_practices(reports)
    anti_patterns = extract_anti_patterns(reports)

    # 生成经验总结
    summary = {
        'analysis_date': get_current_date(),
        'total_reports': len(reports),
        'date_range': get_date_range(reports),
        'top_prompts': rank_by_effectiveness(prompts)[:10],
        'common_patterns': patterns,
        'frequent_errors': error_stats,
        'best_practices': best_practices,
        'anti_patterns': anti_patterns,
        'metrics_summary': calculate_aggregate_metrics(reports)
    }

    return summary


def extract_all_prompts(reports: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """提取所有用户提示词"""
    prompts = []

    for report in reports:
        user_prompts_section = report.get('user_prompts', '')
        if user_prompts_section:
            # 简单提取，实际可以更复杂
            prompt_lines = [line.strip() for line in user_prompts_section.split('\n') if line.strip()]
            for line in prompt_lines:
                if line and not line.startswith('#'):
                    prompts.append({
                        'text': line,
                        'report': report.get('file_path', ''),
                        'success': report.get('metrics', {}).get('success_rate', 0)
                    })

    return prompts


def rank_by_effectiveness(prompts: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """根据成功率排序提示词"""
    # 按成功率排序
    sorted_prompts = sorted(prompts, key=lambda x: x.get('success', 0), reverse=True)

    # 去重并统计使用次数
    unique_prompts = {}
    for prompt in sorted_prompts:
        text = prompt['text']
        if text not in unique_prompts:
            unique_prompts[text] = {
                'text': text,
                'count': 1,
                'avg_success_rate': prompt['success']
            }
        else:
            unique_prompts[text]['count'] += 1

    return list(unique_prompts.values())


def identify_patterns(reports: List[Dict[str, Any]]) -> List[Dict[str, str]]:
    """识别重复出现的模式"""
    patterns = []
    pattern_texts = []

    for report in reports:
        patterns_section = report.get('patterns', '')
        if patterns_section:
            # 提取模式
            lines = patterns_section.split('\n')
            for line in lines:
                if line.strip() and not line.startswith('#'):
                    pattern_texts.append(line.strip())

    # 统计频率
    pattern_counter = Counter(pattern_texts)

    # 返回出现2次以上的模式
    for pattern, count in pattern_counter.most_common():
        if count >= 2:
            patterns.append({
                'pattern': pattern,
                'frequency': count
            })

    return patterns


def analyze_errors(reports: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """分析常见错误"""
    error_types = defaultdict(lambda: {'count': 0, 'solutions': []})

    for report in reports:
        errors_section = report.get('errors', '')
        if errors_section:
            # 简单的错误类型提取
            # 实际应该更复杂的解析
            if 'TypeError' in errors_section:
                error_types['TypeError']['count'] += 1
            if 'CORS' in errors_section:
                error_types['CORS']['count'] += 1
            if '类型错误' in errors_section:
                error_types['类型错误']['count'] += 1

    # 转换为列表
    error_stats = []
    for error_type, data in error_types.items():
        error_stats.append({
            'type': error_type,
            'count': data['count']
        })

    # 按频率排序
    error_stats.sort(key=lambda x: x['count'], reverse=True)

    return error_stats


def extract_best_practices(reports: List[Dict[str, Any]]) -> List[str]:
    """提取最佳实践"""
    practices = []

    for report in reports:
        insights_section = report.get('insights', '')
        if insights_section:
            lines = insights_section.split('\n')
            for line in lines:
                if line.strip() and not line.startswith('#'):
                    practices.append(line.strip())

    # 去重
    return list(set(practices))


def extract_anti_patterns(reports: List[Dict[str, Any]]) -> List[str]:
    """提取反模式"""
    anti_patterns = []

    for report in reports:
        anti_patterns_section = report.get('anti_patterns', '')
        if anti_patterns_section:
            lines = anti_patterns_section.split('\n')
            for line in lines:
                if line.strip() and not line.startswith('#'):
                    anti_patterns.append(line.strip())

    # 去重
    return list(set(anti_patterns))


def calculate_aggregate_metrics(reports: List[Dict[str, Any]]) -> Dict[str, Any]:
    """计算聚合指标"""
    total_errors = 0
    total_iterations = 0
    success_rates = []
    total_steps = 0

    for report in reports:
        metrics = report.get('metrics', {})
        total_errors += metrics.get('total_errors', 0)
        total_iterations += metrics.get('iterations_count', 0)
        if 'success_rate' in metrics:
            success_rates.append(metrics['success_rate'])
        total_steps += metrics.get('workflow_steps_count', 0)

    return {
        'total_errors': total_errors,
        'avg_errors_per_report': total_errors / len(reports) if reports else 0,
        'total_iterations': total_iterations,
        'avg_iterations_per_report': total_iterations / len(reports) if reports else 0,
        'avg_success_rate': sum(success_rates) / len(success_rates) if success_rates else 0,
        'total_workflow_steps': total_steps,
        'avg_steps_per_report': total_steps / len(reports) if reports else 0
    }


def get_current_date() -> str:
    """获取当前日期"""
    from datetime import datetime
    return datetime.now().strftime('%Y-%m-%d')


def get_date_range(reports: List[Dict[str, Any]]) -> Dict[str, str]:
    """获取报告的日期范围"""
    dates = []
    for report in reports:
        date = report.get('metadata', {}).get('date', '')
        if date:
            dates.append(date)

    if dates:
        return {
            'start': min(dates),
            'end': max(dates)
        }
    return {'start': '', 'end': ''}


def save_experience_summary(summary: Dict[str, Any], output_path: str):
    """保存经验总结"""
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(summary, f, ensure_ascii=False, indent=2)


if __name__ == '__main__':
    import sys

    if len(sys.argv) < 2:
        print("Usage: python distill_experience.py <reports_dir>")
        sys.exit(1)

    reports_dir = sys.argv[1]

    if not os.path.isdir(reports_dir):
        print(f"Error: {reports_dir} is not a valid directory")
        sys.exit(1)

    # 提炼经验
    summary = distill_experience(reports_dir)

    # 保存结果
    output_path = os.path.join(reports_dir, 'experience_summary.json')
    save_experience_summary(summary, output_path)

    print(f"Experience summary saved to {output_path}")
    print(f"\nSummary:")
    print(f"- Total reports analyzed: {summary.get('total_reports', 0)}")
    print(f"- Top prompts identified: {len(summary.get('top_prompts', []))}")
    print(f"- Common patterns: {len(summary.get('common_patterns', []))}")
    print(f"- Frequent errors: {len(summary.get('frequent_errors', []))}")

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Git Sync Module for Knowledge Steward
Handles automatic git operations for syncing notes to GitHub
"""

import os
import sys
import subprocess
import logging
from pathlib import Path
from datetime import datetime
from typing import Dict, Optional, Tuple
import yaml

# Fix Windows console encoding
if sys.platform == 'win32':
    import codecs
    # Only wrap if not already wrapped and buffer exists
    if hasattr(sys.stdout, 'buffer') and not isinstance(sys.stdout, codecs.StreamWriter):
        sys.stdout = codecs.getwriter('utf-8')(sys.stdout.buffer, 'strict')
    if hasattr(sys.stderr, 'buffer') and not isinstance(sys.stderr, codecs.StreamWriter):
        sys.stderr = codecs.getwriter('utf-8')(sys.stderr.buffer, 'strict')

# Configure logging
def setup_logging(config: Dict) -> logging.Logger:
    """Setup logging based on configuration"""
    logger = logging.getLogger('git_sync')
    logger.setLevel(getattr(logging, config.get('logging', {}).get('level', 'INFO')))

    # Create logs directory if it doesn't exist
    skill_path = Path(__file__).parent.parent
    log_dir = skill_path / 'logs'
    log_dir.mkdir(exist_ok=True)

    # Extract just the filename from the config path
    log_file_config = config.get('logging', {}).get('file', 'logs/git_sync.log')
    log_filename = Path(log_file_config).name  # Get just the filename, not the path
    log_file = log_dir / log_filename

    # File handler
    handler = logging.FileHandler(log_file, encoding='utf-8')
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    handler.setFormatter(formatter)
    logger.addHandler(handler)

    return logger

def load_config(config_path: Optional[str] = None) -> Dict:
    """Load configuration from YAML file"""
    if config_path is None:
        # Default config path
        skill_path = Path(__file__).parent.parent
        config_path = skill_path / 'config.yaml'

    config_path = Path(config_path)

    if not config_path.exists():
        # Return default config if file doesn't exist
        return {
            'git': {'enabled': False},
            'logging': {'enabled': True, 'level': 'INFO', 'file': 'logs/git_sync.log'}
        }

    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            config = yaml.safe_load(f)
        return config
    except Exception as e:
        print(f"Error loading config: {e}")
        return {'git': {'enabled': False}}

def is_git_available() -> bool:
    """Check if git is installed and available"""
    try:
        result = subprocess.run(
            ['git', '--version'],
            capture_output=True,
            text=True,
            timeout=5
        )
        return result.returncode == 0
    except (subprocess.TimeoutExpired, FileNotFoundError):
        return False

def run_git_command(command: list, cwd: str, logger: Optional[logging.Logger] = None) -> Tuple[bool, str, str]:
    """
    Run a git command and return success status, stdout, stderr

    Args:
        command: Git command as list (e.g., ['git', 'status'])
        cwd: Working directory
        logger: Optional logger for logging operations

    Returns:
        Tuple of (success, stdout, stderr)
    """
    try:
        if logger:
            logger.debug(f"Running command: {' '.join(command)} in {cwd}")

        result = subprocess.run(
            command,
            cwd=cwd,
            capture_output=True,
            text=True,
            encoding='utf-8',
            timeout=30
        )

        success = result.returncode == 0

        if logger:
            if success:
                logger.debug(f"Command succeeded: {result.stdout[:200]}")
            else:
                logger.warning(f"Command failed: {result.stderr[:200]}")

        return success, result.stdout, result.stderr

    except subprocess.TimeoutExpired:
        error_msg = "Git command timed out"
        if logger:
            logger.error(error_msg)
        return False, "", error_msg

    except Exception as e:
        error_msg = f"Error running git command: {str(e)}"
        if logger:
            logger.error(error_msg)
        return False, "", error_msg

def is_git_repo(path: str) -> bool:
    """Check if directory is a git repository"""
    git_dir = Path(path) / '.git'
    return git_dir.exists()

def has_changes(path: str, logger: Optional[logging.Logger] = None) -> bool:
    """Check if there are uncommitted changes"""
    success, stdout, stderr = run_git_command(['git', 'status', '--porcelain'], path, logger)
    return success and len(stdout.strip()) > 0

def init_repo(path: str, remote_url: str, logger: Optional[logging.Logger] = None) -> Dict:
    """
    Initialize a git repository if not already initialized

    Args:
        path: Directory path
        remote_url: GitHub repository URL
        logger: Optional logger

    Returns:
        Dict with 'success' and 'message' keys
    """
    path = Path(path)

    if not path.exists():
        return {'success': False, 'message': f"Directory does not exist: {path}"}

    # Check if already a git repo
    if is_git_repo(str(path)):
        if logger:
            logger.info(f"Directory is already a git repository: {path}")
        return {'success': True, 'message': 'Already a git repository'}

    # Initialize git
    success, stdout, stderr = run_git_command(['git', 'init'], str(path), logger)
    if not success:
        return {'success': False, 'message': f"Failed to initialize git: {stderr}"}

    # Add remote
    success, stdout, stderr = run_git_command(
        ['git', 'remote', 'add', 'origin', remote_url],
        str(path),
        logger
    )
    if not success:
        return {'success': False, 'message': f"Failed to add remote: {stderr}"}

    if logger:
        logger.info(f"Initialized git repository at {path} with remote {remote_url}")

    return {'success': True, 'message': 'Repository initialized successfully'}

def sync_changes(
    path: str,
    commit_message: str,
    config: Optional[Dict] = None,
    auto_pull: bool = True,
    logger: Optional[logging.Logger] = None
) -> Dict:
    """
    Main sync function: pull, commit, and push changes

    Args:
        path: Directory path to sync
        commit_message: Commit message
        config: Configuration dict
        auto_pull: Whether to pull before push
        logger: Optional logger

    Returns:
        Dict with 'success', 'message', and optional 'error' keys
    """
    path = Path(path)

    # Check if git is available
    if not is_git_available():
        error_msg = "Git is not installed or not available in PATH"
        if logger:
            logger.error(error_msg)
        return {'success': False, 'message': error_msg, 'error': 'git_not_available'}

    # Check if it's a git repo
    if not is_git_repo(str(path)):
        error_msg = f"Not a git repository: {path}"
        if logger:
            logger.error(error_msg)
        return {'success': False, 'message': error_msg, 'error': 'not_git_repo'}

    # Pull if auto_pull enabled
    if auto_pull:
        if logger:
            logger.info("Pulling latest changes from remote")

        # Fetch first
        success, stdout, stderr = run_git_command(['git', 'fetch', 'origin'], str(path), logger)
        if not success:
            if logger:
                logger.warning(f"Failed to fetch: {stderr}")

        # Check if remote has changes
        success, stdout, stderr = run_git_command(
            ['git', 'rev-list', 'HEAD...origin/main', '--count'],
            str(path),
            logger
        )

        if success and stdout.strip() != '0':
            # Remote has changes, pull them
            success, stdout, stderr = run_git_command(
                ['git', 'pull', '--rebase', 'origin', 'main'],
                str(path),
                logger
            )
            if not success:
                if logger:
                    logger.warning(f"Failed to pull: {stderr}")

    # Check if there are changes to commit
    if not has_changes(str(path), logger):
        if logger:
            logger.info("No changes to commit")
        return {'success': True, 'message': 'No changes to commit'}

    # Stage all changes
    success, stdout, stderr = run_git_command(['git', 'add', '.'], str(path), logger)
    if not success:
        error_msg = f"Failed to stage changes: {stderr}"
        if logger:
            logger.error(error_msg)
        return {'success': False, 'message': error_msg, 'error': 'stage_failed'}

    # Commit
    success, stdout, stderr = run_git_command(
        ['git', 'commit', '-m', commit_message],
        str(path),
        logger
    )
    if not success:
        error_msg = f"Failed to commit: {stderr}"
        if logger:
            logger.error(error_msg)
        return {'success': False, 'message': error_msg, 'error': 'commit_failed'}

    # Push
    max_retries = config.get('sync', {}).get('max_retries', 3) if config else 3
    retry_delay = config.get('sync', {}).get('retry_delay_seconds', 5) if config else 5

    for attempt in range(max_retries):
        success, stdout, stderr = run_git_command(
            ['git', 'push', 'origin', 'main'],
            str(path),
            logger
        )

        if success:
            if logger:
                logger.info(f"Successfully pushed changes: {commit_message}")
            return {'success': True, 'message': 'Changes synced successfully'}

        if attempt < max_retries - 1:
            if logger:
                logger.warning(f"Push failed (attempt {attempt + 1}/{max_retries}): {stderr}")
            import time
            time.sleep(retry_delay)
        else:
            error_msg = f"Failed to push after {max_retries} attempts: {stderr}"
            if logger:
                logger.error(error_msg)
            return {'success': False, 'message': error_msg, 'error': 'push_failed'}

    return {'success': False, 'message': 'Unknown error', 'error': 'unknown'}

def handle_error(error: str, logger: Optional[logging.Logger] = None) -> str:
    """
    Provide user-friendly error messages

    Args:
        error: Error code
        logger: Optional logger

    Returns:
        User-friendly error message
    """
    error_messages = {
        'git_not_available': '错误：未安装 Git 或 Git 不在 PATH 中。请安装 Git for Windows。',
        'not_git_repo': '错误：目录不是 Git 仓库。请先运行 init_git_repos.py 初始化。',
        'stage_failed': '错误：无法暂存更改。请检查文件权限。',
        'commit_failed': '错误：无法提交更改。请检查 Git 配置。',
        'push_failed': '错误：无法推送到 GitHub。请检查网络连接和认证。',
        'network_error': '错误：网络连接失败。请检查网络设置。',
        'auth_error': '错误：认证失败。请检查 GitHub 凭据。',
    }

    message = error_messages.get(error, f'未知错误：{error}')

    if logger:
        logger.error(message)

    return message

# CLI interface for testing
if __name__ == '__main__':
    import argparse

    parser = argparse.ArgumentParser(description='Git Sync Module')
    parser.add_argument('--test-config', action='store_true', help='Test configuration loading')
    parser.add_argument('--check-git', action='store_true', help='Check if git is available')
    parser.add_argument('--sync', type=str, help='Sync directory')
    parser.add_argument('--message', type=str, default='Test commit', help='Commit message')

    args = parser.parse_args()

    if args.test_config:
        config = load_config()
        print("Configuration loaded successfully:")
        print(yaml.dump(config, default_flow_style=False))

    elif args.check_git:
        if is_git_available():
            print("✓ Git is available")
        else:
            print("✗ Git is not available")

    elif args.sync:
        config = load_config()
        logger = setup_logging(config)
        result = sync_changes(args.sync, args.message, config, logger=logger)
        print(f"Sync result: {result}")
